function fillEll85(cx, cy, rx, ry, col, a) { if (a <= 0) return; ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.fill(); ctx.restore(); }
function cell85(x, y, w, h, s, col, a, size = 20, fillA = 0.3) { if (a <= 0) return; fillBox(x, y, w, h, col, a * fillA); rect63(x, y, w, h, col, a, 1.6); lbl(s, x + w / 2, y + h / 2 + size * 0.35, C.white, a, size); }
/* map a data box onto a screen box */
function sc85(px, py, pw, ph, x0, x1, y0, y1) { return [x => px + (x - x0) / (x1 - x0) * pw, y => py - (y - y0) / (y1 - y0) * ph]; }
/* polyline through data points, broken where the value jumps */
function poly85(pts, xS, yS, col, a, lw = 3, jump = 1e9, prog = 1) {
  if (a <= 0) return;
  const n = Math.max(2, Math.floor(pts.length * clamp(prog)));
  ctx.save(); ctx.globalAlpha = a; ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.lineJoin = 'round'; ctx.beginPath();
  for (let i = 0; i < n; i++) { const [x, y] = pts[i]; if (i === 0 || Math.abs(y - pts[i - 1][1]) > jump) ctx.moveTo(xS(x), yS(y)); else ctx.lineTo(xS(x), yS(y)); }
  ctx.stroke(); ctx.restore();
}
/* series emblem: a ring carrying a predictive wave, a mirror and a reflected pair of points */
function emblem85(cx, cy, r, a, t) {
  if (a <= 0) return;
  ring(cx, cy, r, C.cyan, a * 0.7, 2.5);
  curve(p => { const q = p * TAU; const rr = r * (0.84 + 0.07 * Math.sin(9 * q + t * 1.3)); return [cx + rr * Math.cos(q), cy + rr * Math.sin(q)]; }, 240, C.gold, a * 0.9, 2.5);
  dashed(cx, cy - r * 0.95, cx, cy + r * 0.95, C.white, a * 0.6, 2);
  const hx = ringPts(cx, cy, r * 0.5, 6, -Math.PI / 2); strokePoly(hx, C.vio, a * 0.5, 1.6);
  const dx = r * 0.42, dy = -r * 0.18 + r * 0.06 * Math.sin(t * 0.8);
  ctx.save(); ctx.setLineDash([6, 6]); ctx.globalAlpha = a * 0.8; ctx.strokeStyle = C.mag; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(cx, cy + dy + r * 0.55, Math.hypot(dx, r * 0.55), -Math.PI / 2 - Math.atan2(dx, r * 0.55), -Math.PI / 2 + Math.atan2(dx, r * 0.55)); ctx.stroke(); ctx.restore();
  dot(cx + dx, cy + dy, 14, 'c', a); dot(cx - dx, cy + dy, 14, 'm', a);
  dot(cx, cy + r * 0.32, 9, 'g', a * 0.9);
}
/* a disc of the closed ball with its axis e and a shaded reflection side */
function ball85(cx, cy, R, a, side = 0) {
  if (a <= 0) return;
  if (side > 0) { ctx.save(); ctx.globalAlpha = a * side * 0.16; ctx.fillStyle = C.mag; ctx.beginPath(); ctx.arc(cx, cy, R, Math.PI / 2, Math.PI * 1.5); ctx.closePath(); ctx.fill(); ctx.restore(); }
  ring(cx, cy, R, C.cyan, a, 2.4);
  dashed(cx - R - 30, cy, cx + R + 40, cy, C.dim, a * 0.8, 1.5); lbl('e', cx + R + 58, cy + 7, C.dim, a, 20);
  dashed(cx, cy - R - 20, cx, cy + R + 20, C.dim, a * 0.4, 1.2);
}

