      dot(xS(rmax), yS(Math.min(0.6, rmax * (0.2 + Math.abs(rmax - 1)))), 11, 'm', sq);
      dashed(xS(rmax), py, xS(rmax), yS(Math.min(0.6, rmax * (0.2 + Math.abs(rmax - 1)))), C.mag, sq, 1.6);
      lbl('R(δ) = ' + rmax.toFixed(2), xS(rmax) + 14, py - 30, C.mag, sq, 18, 'left');
